// 1. AI node se aane wale data ko uthein
let rawData = items[0].json; 

// 2. Agar data pehle se string form mein hai ya kisi key ke andar band hai, usko nikalen
// फर्ज karen agar output direct text mein hai ya output key mein hai:
let jsonString = rawData.output || rawData.text || rawData;

// Agar input direct object nahi hai to usko pure JSON object mein convert karen
if (typeof jsonString === 'string') {
    try {
        // Agar markdown backticks (```json) lage hon to unhe saaf karen
        jsonString = jsonString.replace(/```json|```/g, '').trim();
        rawData = JSON.parse(jsonString);
    } catch (e) {
        // Agar parse na ho sake to error se bachne ke liye original hi rakhen
    }
} else {
    rawData = jsonString;
}

// 3. Email bodies ke andar se "\n" ko asli clear text aur neat formatting mein convert karen
return [
  {
    json: {
      lead_rating: rawData.lead_rating,
      reasoning: rawData.reasoning,
      customer_email_subject: rawData.customer_email_subject,
      // Isse line breaks bilkul neat text mein convert ho jayenge
      customer_email_body: rawData.customer_email_body ? rawData.customer_email_body.replace(/\\n/g, '\n') : '',
      owner_email_subject: rawData.owner_email_subject,
      owner_email_body: rawData.owner_email_body ? rawData.owner_email_body.replace(/\\n/g, '\n') : ''
    }
  }
];

